List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    _permute(nums, 0, result);
    return result;
}

void _permute(int[] nums, int start, List<List<Integer>> result) {
    if (start == nums.length) {
        // base case: add the current permutation to the result
        result.add(new ArrayList<>(Arrays.asList(nums)));
        return;
    }

    for (int i = start; i < nums.length; i++) {
        // swap the current element with each element after it
        for (int j = i + 1; j < nums.length; j++) {
            swap(nums, i, j);
        }

        // recurse with the next element as the new start
        _permute(nums, i + 1, result);

        // restore the original array
        for (int j = i + 1; j < nums.length; j++) {
            swap(nums, i, j);
        }
    }
}

void swap(int[] nums, int i, int j) {
    int tmp = nums[i];
    nums[i] = nums[j];
    nums[j] = tmp;
}
