public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> results = new ArrayList<>();
    if (nums.length == 1) {
        results.add(Arrays.asList(nums));
        return results;
    }
    for (int i = 0; i < nums.length; i++) {
        int num = nums[i];
        List<Integer> remainingNums = Arrays.asList(nums).subList(0, i).stream().filter(n -> n != num).collect(Collectors.toList());
        List<List<Integer>> permutations = permute(remainingNums.toArray());
        permutations.forEach(p -> p.add(0, num));
        results.addAll(permutations);
    }
    return results;
}
