public String findLargestSubstringHelper(String string) {
	// If the string is empty, return an empty string
	if (string.isEmpty()) {
		return "";
	}

	// Initialize variables to keep track of the largest substring and its length
	String largestSubstring = "";
	int longestLength = 0;

	// Iterate over each character in the current string
	for (int i = 0; i < string.length(); i++) {
		// Find the longest substring starting from the current character that is a valid solution
		String substring = findLargestSubstringHelper(string.substring(i));

		// Check if the substring is longer than the current largest substring
		if (substring.length() > longestLength) {
			largestSubstring = substring;
			longestLength = substring.length();
		}
	}

	return largestSubstring;
}

