public static int countOilDeposits(char[][] grid) {
    // Initialize variables to keep track of the number of distinct oil deposits
    int numDeposits = 0;
    // Create a set to store the visited oil pockets
    Set<String> visited = new HashSet<>();

    // Loop through each row of the grid
    for (int i = 0; i < grid.length; i++) {
        // Loop through each column of the current row
        for (int j = 0; j < grid[i].length; j++) {
            // If the current cell is an oil pocket, mark it as visited and increment the number of distinct oil deposits
            if (grid[i][j] == '@') {
                visited.add(i + " " + j);
                numDeposits++;
            }
            // If the current cell is not an oil pocket, check if it has already been visited
            else if (!visited.contains(i + " " + j)) {
                // If the current cell has not been visited, check if it is a part of an oil pocket that has already been visited
                for (int k = i - 1; k >= 0; k--) {
                    if (grid[k][j] == '@') {
                        visited.add(i + " " + j);
                        numDeposits++;
                        break;
                    }
                }
                for (int k = j - 1; k >= 0; k--) {
                    if (grid[i][k] == '@') {
                        visited.add(i + " " + j);
                        numDeposits++;
                        break;
                    }
                }
            }
        }
    }

    return numDeposits;
}
