import java.util.HashSet;
import java.util.Set;

public class OilDeposits {
    public static int countOilDeposits(char[][] grid) {
        // Initialize a set to store the visited oil deposits
        Set<String> visited = new HashSet<>();

        // Iterate over the grid and mark the oil deposits as visited
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] == '@') {
                    visitOilDeposit(i, j, grid, visited);
                }
            }
        }

        // Return the size of the set
        return visited.size();
    }

    /**
     * Recursively visit an oil deposit and mark it as visited
     *
     * @param i      The row index of the oil deposit
     * @param j      The column index of the oil deposit
     * @param grid   The grid representing the land
     * @param visited The set of visited oil deposits
     */
    private static void visitOilDeposit(int i, int j, char[][] grid, Set<String> visited) {
        // Mark the current oil deposit as visited
        visited.add(i + " " + j);

        // Visit the neighbors if they are oil deposits
        if (i > 0 && grid[i - 1][j] == '@') {
            visitOilDeposit(i - 1, j, grid, visited);
        }
        if (j > 0 && grid[i][j - 1] == '@') {
            visitOilDeposit(i, j - 1, grid, visited);
        }
        if (i < grid.length - 1 && grid[i + 1][j] == '@') {
            visitOilDeposit(i + 1, j, grid, visited);
        }
        if (j < grid[i].length - 1 && grid[i][j + 1] == '@') {
            visitOilDeposit(i, j + 1, grid, visited);
        }
    }
}
