private int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Do DFS from node 0 and keep track of the minimum time required to reach node 0
    // while collecting all the apples along the way
    int[] dist = new int[n];
    Arrays.fill(dist, -1);
    dist[0] = 0;
    PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
    pq.offer(new int[] {0, 0});
    while (!pq.isEmpty()) {
        int[] curr = pq.poll();
        int node = curr[0];
        int time = curr[1];
        if (dist[node] != -1 && dist[node] <= time) continue;
        dist[node] = time;
        // If the current node has an apple, add its weight to the time
        if (hasApple[node]) time += node;
        // Iterate through the neighbors of the current node and enqueue them
        for (int[] edge : edges[node]) {
            int neighbor = edge[0] == node ? edge[1] : edge[0];
            if (dist[neighbor] == -1) {
                pq.offer(new int[] {neighbor, time + 1});
            }
        }
    }
    // Return the minimum time required to collect all the apples and return to node 0
    return dist[0];
}

