public boolean splitArraySameAverage(int[] nums) {
    // Calculate the average of the input array
    int average = 0;
    for (int num : nums) {
        average += num;
    }
    average /= nums.length;

    // Initialize two arrays to store the first and second halves of the input array
    int[] firstHalf = new int[nums.length / 2];
    int[] secondHalf = new int[nums.length - firstHalf.length];

    // Fill the first half of the array with numbers that are less than the average
    int index = 0;
    for (int i = 0; i < nums.length; i++) {
        if (nums[i] < average) {
            firstHalf[index++] = nums[i];
        }
    }

    // Fill the second half of the array with numbers that are greater than the average
    index = 0;
    for (int i = 0; i < nums.length; i++) {
        if (nums[i] >= average) {
            secondHalf[index++] = nums[i];
        }
    }

    // Check if the average of the two arrays is equal to the average of the input array
    double firstHalfAverage = 0;
    for (int num : firstHalf) {
        firstHalfAverage += num;
    }
    firstHalfAverage /= firstHalf.length;

    double secondHalfAverage = 0;
    for (int num : secondHalf) {
        secondHalfAverage += num;
    }
    secondHalfAverage /= secondHalf.length;

    return firstHalfAverage == secondHalfAverage;
}
