public int findMinFibonacciNumbers(int k) {
    // Initialize a hash map to store the Fibonacci numbers and their indices
    Map<Integer, Integer> fibNumbers = new HashMap<>();
    fibNumbers.put(0, 0); // F0 = 0
    fibNumbers.put(1, 1); // F1 = 1
    int n = 2; // Initialize the number of Fibonacci numbers

    // Iterate until the sum of the Fibonacci numbers is greater than or equal to k
    while (fibNumbers.values().stream().reduce(0, Integer::sum) < k) {
        // Calculate the next Fibonacci number
        int fibNumber = fibNumbers.get(n - 1) + fibNumbers.get(n - 2);
        // Store the Fibonacci number and its index in the hash map
        fibNumbers.put(n, fibNumber);
        n++;
    }

    // Count the number of Fibonacci numbers needed to sum up to k
    int count = 0;
    for (int fibNumber : fibNumbers.values()) {
        if (fibNumber <= k) {
            count++;
        }
    }
    return count;
}

