  for (char c : s.toCharArray()) {
    // If the current character is an uppercase letter, add it to the hash set
    if (Character.isUpperCase(c)) {
      uppercaseLetters.add(c);
    }
    // If the current character is a lowercase letter and the corresponding uppercase letter exists in the hash set
    else if (Character.isLowerCase(c) && uppercaseLetters.contains(Character.toUpperCase(c))) {
      // Remove the adjacent uppercase letter from the hash set
      uppercaseLetters.remove(Character.toUpperCase(c));
    } else {
      // Add the current character to the result string builder
      result.append(c);
    }
  }

  // Return the result string
  return result.toString();
}

