import java.util.ArrayList;
import java.util.List;

public class KClosestElements {
    public static List<Integer> findKClosestElements(int[] arr, int k, int x) {
        List<Integer> result = new ArrayList<>();

        // initialize a priority queue to store the closest elements
        PriorityQueue<Integer> pq = new PriorityQueue<>();

        // loop through the array
        for (int i = 0; i < arr.length; i++) {
            // if the size of the priority queue is less than k, add the current element to the queue
            if (pq.size() < k) {
                pq.offer(arr[i]);
            } else {
                // if the absolute difference between the current element and x is smaller than the absolute difference
                // between the minimum element in the queue and x, remove the minimum element and add the current element
                if (Math.abs(x - arr[i]) < Math.abs(pq.peek() - x)) {
                    pq.poll();
                    pq.offer(arr[i]);
                }
            }
        }

        // loop through the priority queue and add the elements to the result list
        while (!pq.isEmpty()) {
            result.add(pq.poll());
        }

        return result;
    }
}
