    for (i = size - 1; i >= 0; i--) {
        while(i < size - 1 && heights[i] <= heights[i + 1]) {
            i += 1;
        }
        rights[i] = i;
    }

    // Calculate the area with the largest rectangle
    for (i = 0; i < size; i++) {
        maxArea = Math.max(maxArea, (rights[i] - lefts[i] + 1) * heights[i]);
    }

    return maxArea;
