    // starting from the left and right boundaries of the chart.
    int maxArea = 0;
    for (int i = 0; i < heights.length; i++) {
        left[i] = i;
        while (left[i] > 0 && heights[left[i] - 1] >= heights[i]) {
            left[i]--;
