/**
 * Finds the smallest integer that can be formed by rearranging the digits of the given positive integer n.
 *
 * @param n The input positive integer.
 * @return The smallest rearranged integer greater than n, or -1 if not possible.
 */
public static int findSmallestInteger(int n) {
    // Sort the digits of n in ascending order
    int[] digits = new int[10];
    for (int i = 0; i < 10; i++) {
        digits[i] = i;
    }
    for (int i = 0; i < 10; i++) {
        for (int j = i + 1; j < 10; j++) {
            if (digits[i] > digits[j]) {
                int temp = digits[i];
                digits[i] = digits[j];
                digits[j] = temp;
            }
        }
    }

    // Form the rearranged integer
    int rearrangedInt = 0;
    for (int i = 0; i < 10; i++) {
        rearrangedInt = rearrangedInt * 10 + digits[i];
    }

    // Check if the rearranged integer is greater than n
    if (rearrangedInt > n) {
        return rearrangedInt;
    } else {
        return -1;
    }
}

