import java.util.Arrays;

public static boolean isBoomerang(int[][] points) {
    // Sort the points by their x-coordinate
    Arrays.sort(points, (p1, p2) -> p1[0] - p2[0]);

    // Calculate the differences between x-coordinates and y-coordinates
    int[] diffX = new int[points.length - 1];
    int[] diffY = new int[points.length - 1];
    for (int i = 1; i < points.length; i++) {
        diffX[i - 1] = points[i][0] - points[i - 1][0];
        diffY[i - 1] = points[i][1] - points[i - 1][1];
    }

    // Check if the differences between x-coordinates form an increasing sequence
    boolean increasingX = true;
    for (int i = 1; i < diffX.length; i++) {
        if (diffX[i] <= diffX[i - 1]) {
            increasingX = false;
            break;
        }
    }

    // Check if the differences between y-coordinates form a decreasing sequence
    boolean decreasingY = true;
    for (int i = 1; i < diffY.length; i++) {
        if (diffY[i] >= diffY[i - 1]) {
            decreasingY = false;
            break;
        }
    }

    // Return true if the differences between x-coordinates form an increasing sequence, and
    // the differences between y-coordinates form a decreasing sequence
    return increasingX && decreasingY;
}
