public static int minPerfectSquareSum(int n) {
  // Initialize a list to store the unique perfect square numbers
  List<Integer> perfectSquares = new ArrayList<>();
  // Initialize a variable to keep track of the minimum number of perfect square numbers
  int minSquares = 0;
  // Iterate from 1 to n
  for (int i = 1; i <= n; i++) {
    // Check if i is a perfect square
    if (Math.sqrt(i) % 1 == 0) {
      // If i is a perfect square, add it to the list of perfect squares
      perfectSquares.add(i);
      // Increment the minimum number of perfect square numbers
      minSquares++;
    }
  }
  // Return the minimum number of perfect square numbers
  return minSquares;
}

